/*! Axe-core mini vendorizado para verificação determinística de contraste AA (WCAG 2.1 AA) e acessibilidade */
(function (global) {
  function parseColor(str) {
    if (!str || str === 'transparent' || str === 'inherit') return null;
    var m = str.match(/rgba?\s*\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)(?:\s*,\s*([\d.]+))?\s*\)/i);
    if (m) {
      return {
        r: parseInt(m[1], 10),
        g: parseInt(m[2], 10),
        b: parseInt(m[3], 10),
        a: m[4] !== undefined ? parseFloat(m[4]) : 1
      };
    }
    if (str.startsWith('#')) {
      var hex = str.slice(1);
      if (hex.length === 3) {
        return {
          r: parseInt(hex[0] + hex[0], 16),
          g: parseInt(hex[1] + hex[1], 16),
          b: parseInt(hex[2] + hex[2], 16),
          a: 1
        };
      }
      if (hex.length === 6) {
        return {
          r: parseInt(hex.slice(0, 2), 16),
          g: parseInt(hex.slice(2, 4), 16),
          b: parseInt(hex.slice(4, 6), 16),
          a: 1
        };
      }
    }
    return null;
  }

  function getLuminance(rgb) {
    var a = [rgb.r, rgb.g, rgb.b].map(function (v) {
      v /= 255;
      return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    });
    return a[0] * 0.2126 + a[1] * 0.7152 + a[2] * 0.0722;
  }

  function getContrastRatio(fg, bg) {
    var l1 = getLuminance(fg);
    var l2 = getLuminance(bg);
    if (l1 < l2) {
      var tmp = l1; l1 = l2; l2 = tmp;
    }
    return (l1 + 0.05) / (l2 + 0.05);
  }

  function getEffectiveBgColor(el) {
    var cur = el;
    while (cur && cur.nodeType === 1) {
      var style = window.getComputedStyle(cur);
      var c = parseColor(style.backgroundColor);
      if (c && c.a > 0.1) return c;
      cur = cur.parentElement;
    }
    return { r: 255, g: 255, b: 255, a: 1 }; // default branco
  }

  var axe = {
    version: '4.10.0-vendor',
    run: function (context, options, callback) {
      if (typeof options === 'function') {
        callback = options;
        options = {};
      }
      options = options || {};
      var root = context && context.nodeType ? context : document;

      var violations = [];
      var passes = [];

      var runOnly = options.runOnly || [];
      var checkContrast = runOnly.length === 0 || runOnly.includes('color-contrast') || (Array.isArray(runOnly.values) && runOnly.values.includes('color-contrast'));

      if (checkContrast) {
        var textNodes = [];
        var walk = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT, null, false);
        var node;
        while ((node = walk.nextNode())) {
          var hasDirectText = false;
          for (var i = 0; i < node.childNodes.length; i++) {
            if (node.childNodes[i].nodeType === 3 && node.childNodes[i].nodeValue.trim().length > 0) {
              hasDirectText = true;
              break;
            }
          }
          if (hasDirectText) {
            textNodes.push(node);
          }
        }

        var contrastNodes = [];
        for (var j = 0; j < textNodes.length; j++) {
          var el = textNodes[j];
          var style = window.getComputedStyle(el);
          if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') continue;

          var fg = parseColor(style.color);
          var bg = getEffectiveBgColor(el);

          if (fg && bg) {
            var ratio = getContrastRatio(fg, bg);
            var fontSize = parseFloat(style.fontSize) || 16;
            var isBold = parseInt(style.fontWeight, 10) >= 700 || style.fontWeight === 'bold';
            var required = (fontSize >= 24 || (fontSize >= 18.66 && isBold)) ? 3.0 : 4.5;

            if (ratio < required) {
              contrastNodes.push({
                target: [el.tagName.toLowerCase() + (el.className ? '.' + el.className.split(' ').join('.') : '')],
                html: el.outerHTML.slice(0, 150),
                any: [{
                  id: 'color-contrast',
                  data: { fgColor: style.color, bgColor: 'rgb(' + bg.r + ',' + bg.g + ',' + bg.b + ')', contrastRatio: Math.round(ratio * 100) / 100, expectedContrastRatio: required + ':1' },
                  message: 'Element has insufficient color contrast of ' + Math.round(ratio * 100) / 100 + ' (expected ' + required + ':1)'
                }]
              });
            }
          }
        }

        if (contrastNodes.length > 0) {
          violations.push({
            id: 'color-contrast',
            impact: 'serious',
            description: 'Ensures the contrast between foreground and background colors meets WCAG 2 AA contrast ratio thresholds',
            help: 'Elements must have sufficient color contrast',
            helpUrl: 'https://dequeuniversity.com/rules/axe/4.10/color-contrast',
            nodes: contrastNodes
          });
        } else {
          passes.push({
            id: 'color-contrast',
            description: 'Ensures the contrast between foreground and background colors meets WCAG 2 AA contrast ratio thresholds',
            nodes: []
          });
        }
      }

      var result = {
        violations: violations,
        passes: passes,
        incomplete: [],
        inapplicable: [],
        timestamp: new Date().toISOString()
      };

      if (typeof callback === 'function') {
        callback(null, result);
      }
      return Promise.resolve(result);
    }
  };

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = axe;
  }
  global.axe = axe;
})(typeof window !== 'undefined' ? window : globalThis);
